const item = $json;
const headers = item.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const token = String(auth).replace(/^Bearer\s+/i, '').trim();
if (!token) throw new Error('Unauthorized');
const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
const userId = Number(payload.id || payload.userId || payload.sub);
const conversationId = Number(item.params?.id || item.query?.id);
if (!userId || !conversationId) throw new Error('Unauthorized');
return [{ json: { userId, conversationId } }];

const item = $json;
const headers = item.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const token = String(auth).replace(/^Bearer\s+/i, '').trim();
if (!token) throw new Error('Unauthorized');
const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
const userId = Number(payload.id || payload.userId || payload.sub);
const conversationId = Number(item.params?.id || item.query?.id);
const message = String(item.body?.message || '').trim();
const attachment = item.body?.attachment_url || null;
if (!userId || !conversationId || !message) throw new Error('message required');
return [{ json: { userId, conversationId, message, attachment } }];
